    check(this.criteria.id.in(Arrays.asList("id1", "id2"))) .matches("{_id: {$in: ['id1', 'id2']}}");
    check(this.criteria.id.isNot("id1")) .matches("{_id: {$ne: 'id1'}}");
    check(this.criteria.id.notIn(Arrays.asList("id1", "id2"))) .matches("{_id: {$nin: ['id1', 'id2']}}");
  }

  /**
