      this.actual =  agg.toPipeline().stream()
              .map(b -> b.toBsonDocument(BsonDocument.class, codecRegistry))
              .collect(Collectors.toList());
    } else {
      BsonDocument actual = query.filter().map(f -> f.accept(visitor)).orElseGet(BsonDocument::new)
