        path = pathlib.Path(header[len('*** Update File: '):])
        original = path.read_text()
        index += 1
        hunks = []
        current = []
        while index < len(lines) - 1 and not lines[index].startswith('*** '):
            if lines[index].startswith('@@'):
                if current:
                    hunks.append(current)
                    current = []
            else:
                current.append(lines[index])
            index += 1
        if current:
            hunks.append(current)
        updated = original
        for hunk in hunks:
            old = '\n'.join(line[1:] for line in hunk if line.startswith((' ', '-')))
            new = '\n'.join(line[1:] for line in hunk if line.startswith((' ', '+')))
            if old not in updated:
