        path = pathlib.Path(header[len('*** Add File: '):])
        index += 1
        content = []
        while index < len(lines) - 1 and not lines[index].startswith('*** '):
            line = lines[index]
            if not line.startswith('+'):
                raise SystemExit(f'invalid add line: {line}')
            content.append(line[1:])
            index += 1
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('\n'.join(content) + '\n')
    elif header.startswith('*** Delete File: '):
        path = pathlib.Path(header[len('*** Delete File: '):])
        path.unlink()
        index += 1
    else:
        raise SystemExit(f'unknown patch header: {header}')
